SELECT ?point ?p?oType ?tsref WHERE {
  ?zone brick:hasPoint ?point .
  ?zone <http://www.w3.org/2000/01/rdf-schema#label> ?lbl .
  FILTER(?lbl = "Core_mid_ZN_01" || true)
} LIMIT 20

SELECT ?p WHERE {
  ?zone a brick:Zone ; rdfs:label "Core_mid_ZN_01" .
  ?zone brick:hasPoint ?p .
} LIMIT 50

SELECT ?point ?tsref WHERE {
  ?point ref:hasExternalReference ?r .
  ?r ref:hasTimeseriesId ?tsref .
  FILTER(str(?point) CONTAINS ".Zone_Air_Temperature_Sensor")
} LIMIT 60

